from donnees import C,E
CHAPITRES=[
C(9,'Interactions, forces et poids','Comment représenter les actions sur un objet ?',
['Identifier les interactions de contact et à distance.','Représenter une force à une échelle donnée.','Distinguer masse et poids et exploiter P = mg.'],['Masse en kg et vitesse.','Directions et proportionnalité.'],[
('Choisir le système',r'Le système est l’objet ou l’ensemble d’objets que l’on étudie. Un diagramme objet-interactions relie ce système à son environnement : support, fil, air, Terre… Une interaction de contact exige un contact matériel ; la gravitation agit à distance. Le diagramme recense les partenaires ; il ne donne pas à lui seul la valeur des forces.','b09-doi','Une balle suspendue : interactions avec le fil et la Terre ; l’air est négligé dans ce modèle.'),
('Modéliser par une force',r'Une force représente l’action d’un objet sur un autre. On la caractérise par un point d’application, une direction, un sens et une valeur en newtons, N. La flèche part du point choisi ; sa longueur respecte une échelle annoncée. Direction verticale et sens vers le bas sont deux informations différentes. Un dynamomètre mesure une force selon son axe, après contrôle du zéro.','', ''),
('Poids et masse',r'La masse m caractérise la quantité de matière dans les situations étudiées et se mesure en kg avec une balance. Le poids P est une force de pesanteur, en N, mesurée avec un dynamomètre. $P=mg$, avec m en kg et g en N/kg. Près de la surface terrestre, on prend souvent $g=9{,}8$ ou $10\unite{N/kg}$ selon l’énoncé. Le poids est dirigé vers le centre de la Terre dans le modèle local.','b09-poids','Même masse, poids différents : les valeurs de g dépendent du lieu.'),
('Effets et équilibre',r'Une action peut déformer un objet ou modifier son mouvement, en valeur ou en direction. Dans un modèle d’objet immobile soumis à deux forces qui se compensent, elles ont même direction, sens opposés et même valeur. Elles s’exercent sur le même système. Deux forces d’une interaction entre deux objets s’exercent, elles, sur des systèmes différents : on ne les additionne pas sur un seul objet.','', '')],
r'Une trousse de 350 g est immobile sur une table. $m=0{,}350\unite{kg}$, donc $P=0{,}350\times10=3{,}5\unite N$. Dans le modèle à deux forces, le support exerce 3,5 N vers le haut. À 1 cm pour 1 N, chaque flèche mesure 3,5 cm.',
r'Mesurer le poids de plusieurs masses avec un dynamomètre adapté. Tracer P en fonction de m en kg, puis calculer P/m hors zéro. Comparer la pente à la valeur locale de g. Dessiner ensuite les forces sur une masse suspendue immobile, en distinguant les actions sur la masse et sur l’appareil.',
['Nommer l’auteur et le receveur d’une force.','Décrire les quatre caractéristiques d’une flèche.','Convertir les grammes en kilogrammes avant P = mg.'],
'Un objet posé sur une table a un poids. Son immobilité ne signifie pas absence de forces : dans le modèle, l’action du support compense le poids.',[
E('Contact ou distance','Classer l’action d’un fil sur une masse suspendue.@@Classer celle de la Terre sur cette masse.', 'Contact.@@À distance : gravitation.'),
E('Deux appareils','Quel appareil mesure une masse ?@@Quel appareil mesure une force ?', 'Une balance.@@Un dynamomètre.'),
E('Deux unités','Donner l’unité SI de la masse.@@Donner celle du poids.', 'Kilogramme, kg.@@Newton, N.'),
E('Direction et sens','Le poids est-il « vers le bas » ou « vertical » : quelle information donne chaque expression ?@@Citer les deux autres caractéristiques de sa représentation.', 'Vers le bas : sens ; vertical : direction dans le modèle local.@@Point d’application et valeur.'),
E('Un premier calcul',r'Calculer le poids de 2 kg pour $g=10\unite{N/kg}$.@@Une masse de 200 g vaut-elle 200 kg ?',r'$20\unite N$.@@Non : $200\unite g=0{,}200\unite{kg}$.',calculs=[('2*10',20)]),
E('Une petite masse',r'Calculer P pour 150 g et $g=9{,}8\unite{N/kg}$.@@Donner une valeur arrondie au dixième de N.',r'$P=0{,}150\times9{,}8=1{,}47\unite N$.@@Environ $1{,}5\unite N$.',calculs=[('.15*9.8',1.47)]),
E('Retrouver la masse',r'Un objet pèse 24 N pour $g=10\unite{N/kg}$. Déterminer sa masse.@@L’exprimer en g.',r'$m=P/g=2{,}4\unite{kg}$.@@$2\,400\unite g$.',calculs=[('24/10',2.4)]),
E('Changer de lieu',r'Une masse de 60 kg est transportée sur la Lune, avec $g=1{,}6\unite{N/kg}$. Donner masse et poids.@@Comparer à son poids terrestre avec $g=10\unite{N/kg}$.',r'Masse : 60 kg ; poids : 96 N.@@600 N sur Terre ; la masse n’a pas changé.',calculs=[('60*1.6',96),('60*10',600)]),
E('Une échelle',r'Une force de 12 N est représentée à 1 cm pour 4 N. Calculer la longueur.@@Une flèche de 2,5 cm représente quelle valeur à cette échelle ?',r'$12/4=3\unite{cm}$.@@$2{,}5\times4=10\unite N$.',calculs=[('12/4',3),('2.5*4',10)]),
E('Le livre immobile','Nommer les deux partenaires principaux d’un livre immobile sur une table horizontale.@@Décrire leurs forces dans le modèle à deux forces.', 'La Terre et la table.@@Poids vertical vers le bas, action du support verticale vers le haut, de même valeur.'),
E('Une pente mesurée',r'On mesure 1,0 N pour 0,10 kg et 2,0 N pour 0,20 kg. Estimer g.@@Que suggère un graphe linéaire passant près de l’origine ?',r'$P/m=10\unite{N/kg}$ dans les deux cas.@@Une proportionnalité entre P et m compatible avec le modèle, à la précision des mesures.',calculs=[('1/.1',10),('2/.2',10)]),
E('Une mesure négative','Un dynamomètre indique −0,2 N sans charge. Quelle vérification faire ?@@Pourquoi ce décalage gêne-t-il surtout une petite mesure ?', 'Contrôler le zéro et l’orientation selon la notice.@@L’erreur peut représenter une grande part de la petite valeur mesurée.'),
E('Des forces confondues','Un élève dessine sur le livre son poids et la force qu’il exerce sur la table. Quelle erreur commet-il ?@@Quelle force doit remplacer la seconde ?', 'La seconde agit sur la table, pas sur le livre.@@L’action de la table sur le livre.'),
E('Un virage','Une voiture garde une même valeur de vitesse dans un virage. Son mouvement est-il inchangé ?@@Une force peut-elle modifier seulement la direction de la vitesse ?', 'Non, la direction de la vitesse change.@@Oui ; une modification de mouvement ne se limite pas à accélérer ou ralentir en valeur.'),
E('Une affirmation à discuter','« Une force de 5 N suffit toujours à déplacer n’importe quel objet. » Pourquoi faut-il connaître les autres actions ?@@Donner un cas où cette force est compensée.', 'Les effets dépendent de l’ensemble des actions et du système.@@Une masse immobile suspendue peut subir 5 N vers le bas et 5 N vers le haut.')],
E('La caisse suspendue',r'Une caisse de 4,0 kg est suspendue immobile, $g=9{,}8\unite{N/kg}$. Calculer P.@@Décrire les forces à l’échelle 1 cm pour 10 N, en négligeant l’air.@@Pourquoi ces forces de compensation ne sont-elles pas les deux forces d’une même interaction ?',r'$P=39{,}2\unite N$.@@Poids vers le bas et action du câble vers le haut, même direction et valeur ; longueur 3,92 cm chacune, environ 3,9 cm au tracé.@@Elles agissent toutes deux sur la caisse mais proviennent de deux partenaires différents : Terre et câble.',calculs=[('4*9.8',39.2),('39.2/10',3.92)])),
C(10,'Exploiter la gravitation universelle','Comment comparer l’attraction entre deux objets ?',
['Utiliser la loi de gravitation lorsqu’elle est fournie.','Convertir distances et masses en unités SI.','Distinguer gravitation, poids et impesanteur.'],['Puissances de dix et calculatrice.','Forces à distance ; P = mg.'],[
('Une interaction attractive',r'Deux objets possédant une masse s’attirent par gravitation. Les forces sont dirigées selon la droite joignant leurs centres dans le modèle de corps sphériques. Chaque objet exerce une force sur l’autre. Les valeurs sont égales et les sens opposés ; les forces s’appliquent à des objets différents. Ce modèle permet notamment d’étudier l’interaction Terre-Lune.','b10-forces','Deux forces sur deux systèmes ; tailles et distance ne sont pas à l’échelle.'),
('Utiliser la relation fournie',r'Quand l’énoncé la donne, on exploite la relation \[F=G\dfrac{m_A m_B}{d^2}.\] F est en N, les masses en kg et d en m, distance entre les centres. On emploie par exemple $G=6{,}67\times10^{-11}\unite{N\,m^2/kg^2}$. Écrire les conversions avant le calcul, regrouper le dénominateur et vérifier la touche « puissance » de la calculatrice.','', ''),
('Comparer sans tout recalculer',r'À distance inchangée, doubler une masse double F ; doubler les deux masses multiplie F par quatre. À masses inchangées, doubler d divise F par quatre ; tripler d divise F par neuf. Le carré porte sur toute la distance. Ces comparaisons concernent les conditions annoncées et le même modèle.','b10-distance','La force diminue comme l’inverse du carré de la distance, pour des masses fixées.'),
('Du modèle au poids',r'Près de la surface d’un astre, son attraction domine et correspond au poids dans le modèle simplifié. Avec un rayon R, on peut comparer $P=mg$ et $F=GMm/R^2$, sans confondre rayon et altitude. Un satellite en orbite reste attiré : l’impesanteur ressentie à bord correspond à une chute commune, et non à une disparition de la gravitation.','', '')],
r'Deux masses de 10 kg et 20 kg, distantes de 2 m, sont modélisées par $F=Gm_Am_B/d^2$. $F=6{,}67\times10^{-11}\times10\times20/2^2=3{,}335\times10^{-9}\unite N$. Cette force est très faible à l’échelle d’un dynamomètre scolaire ; elle n’est pas nulle.',
r'Utiliser une simulation ou un tableur, avec la loi fournie. Fixer les masses et calculer F pour d, 2d et 3d ; puis fixer d et changer une seule masse. Tracer des points et expliquer pourquoi F en fonction de d ne forme pas une droite. Aucun montage de gravitation sensible n’est exigé au collège.',
['Identifier d comme distance entre les centres.','Calculer avec des kg, m et une loi fournie.','Justifier les facteurs 2, 4 ou 9 par la relation.'],
'Une altitude de 400 km n’est pas la distance au centre de la Terre. Dans ce modèle, il faut ajouter le rayon terrestre avant de convertir et de mettre au carré.',[
E('Nature de l’action','La gravitation est-elle une action de contact ?@@Est-elle attractive dans le modèle étudié ?', 'Non : elle agit à distance.@@Oui.'),
E('Deux objets','La Terre attire la Lune. La Lune attire-t-elle la Terre ?@@Sur quel objet agit la force exercée par la Lune ?', 'Oui, avec une force de même valeur.@@Sur la Terre.'),
E('Unités',r'Dans $F=Gm_A m_B/d^2$, donner les unités de m et d pour obtenir F en N.@@Convertir 6 400 km en m.',r'kg et m.@@$6{,}4\times10^6\unite m$.',calculs=[('6400*1000',6400000)]),
E('Quelle distance ?','Pour deux sphères, quelle distance figure dans la loi donnée ?@@Pourquoi la distance entre leurs surfaces ne suffit-elle pas ?', 'La distance entre leurs centres dans le modèle.@@Il faut aussi connaître les rayons pour retrouver cette distance centrale.'),
E('Une masse doublée','La masse A double, le reste ne change pas. Que devient F ?@@Si les deux masses doublent ?', 'F double.@@F est multipliée par quatre.'),
E('Une distance doublée','Les masses sont fixées et d double. Que devient F ?@@Et si d est divisée par deux ?', 'F est divisée par quatre.@@F est multipliée par quatre.'),
E('Une force modèle',r'Avec $G=6{,}67\times10^{-11}$ en unités SI, calculer F pour 1 kg, 1 kg et 1 m.@@Est-ce une force nulle ?',r'$6{,}67\times10^{-11}\unite N$.@@Non : elle est très faible, même si un appareil scolaire ne la détecte pas.',calculs=[('6.67e-11*1*1/1**2',6.67e-11)]),
E('Une comparaison rapide',r'À d, F vaut 36 N. Quelle valeur à 3d avec les mêmes masses ?@@Quelle valeur à 2d ?',r'$36/9=4\unite N$.@@$36/4=9\unite N$.',calculs=[('36/9',4),('36/4',9)]),
E('Depuis l’orbite',r'Rayon terrestre donné : 6 400 km ; altitude : 400 km. Déterminer d en km puis m.@@Quel terme doit-on mettre au carré ?',r'$d=6\,800\unite{km}=6{,}8\times10^6\unite m$.@@Toute la distance en mètres, donc $(6{,}8\times10^6)^2$.',calculs=[('(6400+400)*1000',6800000)]),
E('Un petit calcul',r'Calculer F pour $m_A=100\unite{kg}$, $m_B=50\unite{kg}$, $d=10\unite m$, $G=6{,}67\times10^{-11}$ en SI.@@Prévoir la valeur si seule $m_B$ devient 100 kg.',r'$F=3{,}335\times10^{-9}\unite N$.@@Elle double : $6{,}67\times10^{-9}\unite N$.',calculs=[('6.67e-11*100*50/10**2',3.335e-9)]),
E('Trois facteurs','La masse A double et d double, B reste fixe. Par quel facteur F est-elle multipliée ?@@Justifier avec la relation.',r'Par $2/4=1/2$.@@La masse au numérateur apporte 2 ; le carré de la distance au dénominateur apporte 4.',calculs=[('2/2**2',.5)]),
E('Un faux équilibre','« Les deux forces Terre-Lune s’annulent, donc la Lune n’est pas attirée. » Quelle erreur de système apparaît ?@@Quelle force faut-il retenir pour étudier seulement la Lune ?', 'Elles s’exercent sur deux objets distincts et ne se compensent pas sur un seul.@@L’attraction exercée par la Terre sur la Lune, avec les autres actions éventuelles du modèle.'),
E('Impesanteur','Pourquoi l’impesanteur dans une station orbitale ne signifie-t-elle pas absence d’attraction ?@@Quelle hypothèse donne l’explication qualitative ?', 'La station et les occupants restent attirés par la Terre.@@Ils sont en chute commune autour de la Terre, hors forces de contact de soutien habituelles.'),
E('Retrouver g',r'La loi fournie donne une force de 588 N sur une masse de 60 kg près du sol. Trouver g à partir de P = mg.@@Quelle masse aurait un poids de 98 N au même lieu ?',r'$g=588/60=9{,}8\unite{N/kg}$.@@$m=98/9{,}8=10\unite{kg}$.',calculs=[('588/60',9.8),('98/9.8',10)]),
E('La précision du modèle','Une calculatrice affiche dix chiffres pour F, mais les distances ont deux chiffres significatifs. Pourquoi éviter une conclusion à dix chiffres ?@@Citer une hypothèse du modèle gravitationnel utilisé.', 'La précision numérique affichée ne corrige pas l’approximation des données.@@Les corps sont assimilés à des sphères ou des masses ponctuelles pour employer la distance entre centres.')],
E('Autour d’une planète',r'Une planète a $M=6{,}0\times10^{24}\unite{kg}$. Un satellite de 500 kg est à $d=7{,}0\times10^6\unite m$. Calculer F avec $G=6{,}67\times10^{-11}$ en SI.@@Si d double, que devient F ?@@Comparer les forces planète-satellite et expliquer pourquoi leurs effets ne sont pas identiques.',r'$F\approx4{,}08\times10^3\unite N$, soit environ $4{,}1\times10^3\unite N$.@@Environ $1{,}02\times10^3\unite N$, par division par quatre.@@Les valeurs sont égales et les sens opposés, mais les forces s’appliquent à deux masses très différentes. Égalité de force ne signifie pas évolution de mouvement identique.',calculs=[('6.67e-11*6e24*500/(7e6)**2',4083.673469387755)])),
C(11,'Énergie cinétique et bilan mécanique','Pourquoi la vitesse pèse-t-elle autant sur un freinage ?',
['Calculer une énergie cinétique en unités SI.','Comparer l’effet de la masse et de la vitesse.','Suivre une conversion et distinguer énergie et force.'],['Vitesse en m/s ; carré d’un nombre.','Conservation et formes d’énergie.'],[
('L’énergie du mouvement',r'Un objet de masse m et de vitesse de valeur v possède, dans le référentiel choisi, une énergie cinétique \[E_c=\dfrac12 mv^2.\] Avec m en kg et v en m/s, $E_c$ est en joules, J. La vitesse se convertit avant le carré : une valeur en km/h doit être divisée par 3,6. Un objet immobile dans le référentiel considéré y a une énergie cinétique nulle.','b11-ec','À masse fixée, le graphe d’Ec en fonction de v n’est pas une droite.'),
('Des facteurs à comparer',r'À vitesse fixée, doubler la masse double l’énergie cinétique. À masse fixée, doubler la vitesse multiplie cette énergie par quatre ; tripler la vitesse la multiplie par neuf. Ces effets expliquent pourquoi une petite augmentation de vitesse peut avoir un effet énergétique important. Le calcul ne donne pas à lui seul une distance d’arrêt : freinage, adhérence, pente et temps de réaction interviennent aussi.','', ''),
('Position et conversion',r'Une énergie potentielle de pesanteur dépend de la position et du choix d’un niveau de référence. Lors d’une chute, elle peut diminuer tandis que l’énergie cinétique augmente. Si les frottements sont négligés, leur somme, l’énergie mécanique, reste constante. Avec frottements, une partie de l’énergie mécanique est transférée ou convertie en énergie thermique ; l’énergie totale d’un système suffisamment large reste conservée.','b11-chute','Modèle de chute : exemple chiffré sans frottement ; le niveau de référence est annoncé.'),
('Freiner et argumenter',r'Freiner réduit l’énergie cinétique et augmente notamment l’énergie thermique des freins, pneus et milieu. L’énergie n’est pas détruite. Une force se mesure en N, une énergie en J, une puissance en W : ce sont des grandeurs distinctes. Au Brevet, comparer les carrés des vitesses peut suffire à justifier un rapport d’énergies sans calculer deux grandes valeurs.','', '')],
r'Pour un ensemble vélo-cycliste de 80 kg à 18 km/h, $v=18/3{,}6=5\unite{m/s}$ ; $E_c=\tfrac12\times80\times5^2=1\,000\unite J$. À 36 km/h, v double : $E_c=4\,000\unite J$. La comparaison suppose la même masse et le même référentiel.',
r'Au tableur, comparer les énergies d’une même masse pour 2, 4, 6 et 8 m/s. Ajouter une colonne $v^2$ et tracer Ec en fonction de v, puis de $v^2$. Exploiter ensuite une vidéo ou une simulation de chute en distinguant modèle sans frottement et observation réelle. Ne pas provoquer de choc dangereux.',
['Écrire Ec avec m en kg et v en m/s.','Justifier l’effet du carré de la vitesse.','Faire un bilan comprenant les sorties thermiques.'],
'Doubler la vitesse ne double pas l’énergie cinétique : dans le modèle, cela la multiplie par quatre. Il faut mettre toute la vitesse convertie au carré.',[
E('La forme d’énergie','Quelle énergie est associée au mouvement d’un objet ?@@Dans quelle unité SI s’exprime-t-elle ?', 'L’énergie cinétique.@@En joules, J.'),
E('Les bonnes unités','Quelles unités de m et v employer dans Ec = ½mv² ?@@Convertir 500 g en kg.',r'kg et m/s.@@$0{,}500\unite{kg}$.'),
E('La vitesse',r'Convertir 36 km/h en m/s.@@Convertir 72 km/h en m/s.',r'$10\unite{m/s}$.@@$20\unite{m/s}$.',calculs=[('36/3.6',10),('72/3.6',20)]),
E('Un calcul direct',r'Calculer Ec pour 2 kg à 3 m/s.@@Que vaut Ec si cet objet est immobile dans le référentiel ?',r'$\tfrac12\times2\times9=9\unite J$.@@$0\unite J$.',calculs=[('.5*2*3**2',9)]),
E('Deux facteurs','À vitesse identique, la masse double. Que devient Ec ?@@À masse identique, la vitesse double ?', 'Ec double.@@Ec est multipliée par quatre.'),
E('Le ballon',r'Un ballon de 400 g va à 5 m/s. Calculer Ec.@@Si v devient 10 m/s, calculer la nouvelle valeur.',r'$E_c=0{,}5\times0{,}400\times25=5\unite J$.@@$20\unite J$.',calculs=[('.5*.4*5**2',5),('.5*.4*10**2',20)]),
E('Une voiture',r'Une voiture de 1 000 kg va à 54 km/h. Déterminer v puis Ec.@@Donner Ec en kJ.',r'$v=15\unite{m/s}$ ; $E_c=112\,500\unite J$.@@$112{,}5\unite{kJ}$.',calculs=[('54/3.6',15),('.5*1000*15**2',112500)]),
E('Ralentir',r'Un ensemble de 60 kg passe de 10 à 5 m/s. Calculer les deux énergies.@@Quelle énergie cinétique est perdue ?',r'$3\,000\unite J$ puis $750\unite J$.@@$2\,250\unite J$, transférés ou convertis, notamment en thermique.',calculs=[('.5*60*10**2',3000),('.5*60*5**2',750),('3000-750',2250)]),
E('Une chute idéale',r'Au départ, Ec = 0 J et Ep = 40 J. Sans frottement, que vaut Ec lorsque Ep = 15 J ?@@Pourquoi faut-il annoncer le modèle ?',r'$E_c=40-15=25\unite J$.@@Les frottements réels peuvent transférer une partie de l’énergie mécanique vers le milieu.',calculs=[('40-15',25)]),
E('Le rapport','À masse fixée, comparer Ec à 30 m/s et à 10 m/s.@@À vitesse fixée, comparer 120 kg et 80 kg.',r'Rapport $3^2=9$.@@Rapport $120/80=1{,}5$.',calculs=[('(30/10)**2',9),('120/80',1.5)]),
E('Une hausse de 20 %','La vitesse est multipliée par 1,2 à masse fixée. Par quel facteur Ec est-elle multipliée ?@@Exprimer l’augmentation en pourcentage.',r'$1{,}2^2=1{,}44$.@@44 %.',calculs=[('1.2**2',1.44)]),
E('Changer de référentiel','Un passager est immobile par rapport à son train. Peut-il avoir une énergie cinétique dans le référentiel du sol ?@@Quelle précision manque à « cet objet n’a aucune énergie cinétique » ?', 'Oui, puisqu’il se déplace par rapport au sol.@@Le référentiel et la vitesse du système dans ce référentiel.'),
E('La force n’est pas l’énergie','Un élève donne une énergie cinétique de 250 N. Corriger l’unité.@@Peut-on trouver une distance de freinage avec seulement Ec ?', '250 J si le calcul est correct.@@Non ; il faut un modèle et des données sur le freinage, la route et les autres actions.'),
E('Un bilan réel',r'Une chute commence avec 100 J d’énergie mécanique et finit avec 85 J. Où les 15 J peuvent-ils être passés ?@@La conservation totale est-elle remise en cause ?', 'Vers de l’énergie thermique du système et du milieu, notamment par frottement.@@Non, à condition d’élargir le bilan aux transferts et aux autres formes d’énergie.'),
E('Comparer deux véhicules',r'A : 800 kg à 20 m/s ; B : 1 600 kg à 10 m/s. Lequel a le plus d’énergie cinétique ?@@Pourquoi comparer seulement les masses donnerait-il une erreur ?',r'A : 160 000 J ; B : 80 000 J. A a deux fois plus d’énergie.@@Le carré de la vitesse compense ici plus que la différence de masse.',calculs=[('.5*800*20**2',160000),('.5*1600*10**2',80000)])],
E('Une étude de sécurité',r'Une voiture et ses occupants ont une masse de 1 200 kg. Comparer Ec à 50 km/h et 100 km/h.@@Expliquer le résultat sans recalculer la seconde énergie.@@Rédiger une conclusion de quatre lignes qui distingue énergie, distance d’arrêt et conditions de freinage.',r'À 50 km/h : $v\approx13{,}89\unite{m/s}$ et $E_c\approx1{,}16\times10^5\unite J$. À 100 km/h : environ $4{,}63\times10^5\unite J$.@@Même masse et vitesse doublée : énergie quadruplée.@@Une vitesse plus grande augmente fortement l’énergie à dissiper. Le calcul suppose le même ensemble et le même référentiel. Il ne donne pas directement la distance d’arrêt. Celle-ci dépend aussi du temps de réaction, de l’adhérence et du freinage.',calculs=[('.5*1200*(50/3.6)**2',115740.74074074075)])),
C(13,'Circuits : intensités et tensions','Quelles lois permettent de contrôler un montage ?',
['Schématiser série et dérivation.','Brancher les appareils et convertir les mesures.','Exploiter les lois des intensités et des tensions.'],['Symboles usuels et circuit fermé.','A, mA et V.'],[
('Lire la topologie',r'Deux dipôles sont en série s’ils appartiennent à une même branche sans dérivation entre eux. Deux dipôles sont en dérivation s’ils sont reliés aux mêmes deux nœuds. Le schéma indique les connexions ; la position sur la feuille ne suffit pas. Une source alimente le circuit fermé. Un court-circuit peut provoquer une intensité élevée et un échauffement : on coupe l’alimentation avant toute modification.','b13-circuits','Topologie de deux circuits : suivre les connexions et repérer les deux nœuds.'),
('Mesurer correctement',r'Un ampèremètre mesure une intensité I et se branche en série dans la branche étudiée. Un voltmètre mesure une tension U et se branche en dérivation aux bornes du dipôle. Utiliser les bornes et le calibre adaptés, commencer par un calibre suffisant et respecter le sens de connexion en courant continu. $1\unite A=1\,000\unite{mA}$. Un affichage négatif peut venir d’une inversion des bornes.','', ''),
('Les lois des intensités',r'Dans une unique branche de dipôles en série, l’intensité du courant est la même en tout point en régime permanent. À un nœud, la somme des intensités entrantes égale celle des intensités sortantes ; avec deux branches réceptrices, $I_G=I_1+I_2$. Le courant n’est pas « consommé » par une lampe : c’est l’énergie qui lui est transférée.','b13-mesures','Ampèremètre en série et voltmètre en dérivation : connexions distinctes.'),
('Les lois des tensions',r'Dans une boucle simple comprenant la source et deux récepteurs en série, avec les valeurs positives et conventions indiquées, $U_G=U_1+U_2$. Deux dipôles reliés aux mêmes deux nœuds ont la même tension : $U_1=U_2=U_G$ dans le montage en dérivation directement alimenté. Ne pas confondre égalité des tensions et égalité des intensités : les courants des branches peuvent différer.','', '')],
r'Deux lampes en dérivation sont soumises à 6,0 V. Les intensités sont 120 mA et 180 mA. La source débite $I_G=0{,}120+0{,}180=0{,}300\unite A$. Chaque lampe reçoit 6,0 V ; cette égalité n’oblige pas les deux courants à être égaux.',
r'Réaliser sous contrôle un circuit scolaire à deux lampes. Mesurer les intensités en série, puis les trois intensités d’un montage en dérivation. Contrôler ensuite les tensions sur les mêmes nœuds. Comparer aux lois, en tenant compte du calibre, de la lecture et de la stabilité de la source.',
['Choisir le bon montage de mesure.','Écrire la loi avant de remplacer les valeurs.','Vérifier la cohérence d’une mesure avec les connexions.'],
'Brancher un ampèremètre directement aux bornes d’une source peut créer un court-circuit. Il ne remplace jamais un voltmètre.',[
E('Le branchement','Comment brancher un ampèremètre ?@@Comment brancher un voltmètre ?', 'En série dans la branche.@@En dérivation aux bornes du dipôle.'),
E('Conversions',r'Convertir 250 mA en A.@@Convertir 0,032 A en mA.',r'$0{,}250\unite A$.@@$32\unite{mA}$.',calculs=[('250/1000',.25),('.032*1000',32)]),
E('En série',r'Dans une seule branche, on mesure 0,18 A avant une lampe. Quelle intensité après ?@@Le courant est-il consommé ?',r'$0{,}18\unite A$ en régime permanent.@@Non ; la lampe reçoit et convertit de l’énergie.'),
E('Deux nœuds','Deux lampes sont reliées aux mêmes deux nœuds. Comment nommer l’association ?@@Quelle grandeur a la même valeur aux bornes des lampes ?', 'En dérivation.@@La tension, avec la même convention de mesure.'),
E('Une somme',r'Deux courants de 0,10 A et 0,25 A sortent d’un nœud. Quelle intensité totale entre ?@@Donner la valeur en mA.',r'$0{,}35\unite A$.@@$350\unite{mA}$.',calculs=[('.1+.25',.35)]),
E('Une branche inconnue',r'$I_G=0{,}80\unite A$, $I_1=250\unite{mA}$. Calculer I2.@@Quelle erreur ferait-on en calculant $0{,}80-250$ ?',r'$I_2=0{,}80-0{,}250=0{,}550\unite A$.@@On mélangerait A et mA.',calculs=[('.8-.25',.55)]),
E('Tensions en série',r'Une source de 9 V alimente deux récepteurs en série. U1 = 3,5 V. Trouver U2.@@Où brancher le voltmètre pour mesurer U2 ?',r'$U_2=9-3{,}5=5{,}5\unite V$.@@Aux bornes du second récepteur, en dérivation.',calculs=[('9-3.5',5.5)]),
E('Tensions en dérivation',r'Deux résistances sont en dérivation sur une source idéale de 12 V. Donner leurs tensions.@@Leurs intensités sont-elles forcément égales ?',r'$U_1=U_2=12\unite V$.@@Non ; elles dépendent des dipôles.'),
E('Une inversion','Un voltmètre affiche −4,5 V. Quelle cause de connexion envisager ?@@L’intensité est-elle pour autant forcément nulle ?', 'Les bornes V et COM peuvent être inversées par rapport à la convention choisie.@@Non ; le signe de cette mesure n’impose pas un courant nul.'),
E('Commander séparément','Deux lampes doivent être commandées indépendamment. Quelle association proposer ?@@Où placer les deux interrupteurs ?', 'Deux branches en dérivation.@@Un interrupteur en série avec sa lampe dans chaque branche.'),
E('Une mesure incohérente',r'En série, un élève mesure 0,20 A puis 0,12 A. La loi est-elle invalidée par ces deux nombres seuls ?@@Citer deux contrôles.', 'Non ; il faut examiner protocole, stabilité et appareils.@@Vérifier les connexions et calibres, puis mesurer dans les mêmes conditions avec un circuit stable.'),
E('Un nœud à trois sorties',r'Entrée : 0,90 A ; sorties connues : 0,20 A et 0,35 A. Calculer la troisième.@@La somme des sorties doit-elle être plus petite que l’entrée en régime permanent ?',r'$0{,}35\unite A$.@@Non : elles sont égales dans le modèle du nœud.',calculs=[('.9-.2-.35',.35)]),
E('Une lampe retirée','Dans un montage en dérivation, on ouvre une branche sans toucher l’autre. L’autre lampe peut-elle rester allumée ?@@Quelle hypothèse sur la source faut-il annoncer pour conserver exactement sa tension ?', 'Oui, son chemin fermé vers la source demeure.@@Une source idéale ou suffisamment stable dans les conditions du montage.'),
E('Court-circuit','Un fil relie directement les deux bornes d’une lampe. Pourquoi la situation est-elle différente d’une branche avec une lampe ?@@Que faire avant de modifier le montage ?', 'Le fil peut imposer une tension très faible à la lampe et créer une circulation de courant importante dans le circuit.@@Couper l’alimentation et faire vérifier le montage.'),
E('Un cahier des charges',r'Deux lampes doivent recevoir chacune 6 V, l’une sous 0,10 A et l’autre sous 0,20 A. Quelle association et quelle intensité de source prévoir ?@@Pourquoi une association en série sur 6 V ne répond-elle pas en général à la demande ?',r'Dérivation sur 6 V ; source capable de fournir au moins 0,30 A dans ce modèle.@@En série, les tensions se partagent et le courant est commun : ces conditions ne donnent pas les deux fonctionnements demandés.',calculs=[('.1+.2',.3)])],
E('Le montage à vérifier',r'Deux branches sont reliées à une source de 9 V. La première comprend deux lampes en série sous 4 V et 5 V ; la seconde une résistance. Vérifier les tensions.@@Les courants de branches valent 150 mA et 60 mA. Trouver IG.@@Décrire un protocole de mesure de la tension de la résistance et du courant de la première branche.',r'La première branche totalise $4+5=9\unite V$ ; la résistance directement en dérivation reçoit aussi 9 V.@@$I_G=0{,}150+0{,}060=0{,}210\unite A$.@@Voltmètre aux bornes de la résistance ; ampèremètre inséré en série dans la première branche, alimentation coupée pendant la modification et contrôle des bornes/calibres.',calculs=[('.15+.06',.21)])),
C(14,'Loi d’Ohm et puissance électrique','Comment prévoir le fonctionnement d’un dipôle ?',
['Exploiter U = RI et une caractéristique.','Calculer P = UI en courant continu.','Contrôler unités, limites et puissance admissible.'],['Lois des circuits et montage A/V.','Proportionnalité.'],[
('Un conducteur ohmique',r'Pour un conducteur ohmique dans des conditions physiques fixées, notamment de température, la tension U est proportionnelle à l’intensité I : $U=RI$. U en V, I en A et R en ohms, $\Omega$. La caractéristique U en fonction de I est une droite passant par l’origine dans le modèle. La pente U/I vaut R. Tous les dipôles ne sont pas ohmiques.','b14-ohm','Résistance de 100 Ω : attention à l’unité de l’axe des intensités.'),
('Isoler l’inconnue',r'On peut écrire $I=U/R$ ou $R=U/I$ pour I non nul. Convertir les mA en A et les k$\Omega$ en $\Omega$. À tension fixée, une résistance plus grande laisse passer une intensité plus faible. Une lampe peut chauffer et présenter une caractéristique différente : on ne lui applique pas automatiquement une résistance constante.','', ''),
('Puissance électrique',r'En courant continu, la puissance électrique reçue par un dipôle vaut $P=UI$, avec P en W, U en V et I en A. La puissance est une énergie transférée par unité de durée. Une puissance nominale décrit un fonctionnement prévu dans les conditions indiquées. Pour un conducteur ohmique, combiner U = RI et P = UI permet de vérifier les risques d’échauffement.','b14-montage','Mesurer U et I avant de calculer P ; ne pas dépasser les caractéristiques du matériel.'),
('Vérifier un choix',r'Une résistance possède une puissance maximale admissible donnée par le fabricant. Un calcul cohérent de R ne garantit pas que l’échauffement soit acceptable. Les montages du collège utilisent une alimentation scolaire adaptée ; les installations domestiques demandent d’autres modèles et des protections. P = UI n’est utilisé ici qu’en courant continu ou dans les cas explicitement simplifiés par l’énoncé.','', '')],
r'Une résistance de $200\unite\Omega$ reçoit $6\unite V$. $I=6/200=0{,}030\unite A=30\unite{mA}$. Sa puissance vaut $P=6\times0{,}030=0{,}18\unite W$. Elle reste inférieure à une limite fournie de 0,25 W ; le professeur vérifie aussi les autres contraintes du montage.',
r'Relever U et I pour une résistance avec une alimentation scolaire réglable, sans dépasser les limites données. Faire un nuage de points U(I) avec I en A. Comparer les quotients hors origine et l’alignement, puis calculer la puissance au point le plus élevé. Signaler toute dérive due à l’échauffement.',
['Reconnaître et exploiter une proportionnalité U/I.','Écrire et convertir avant de calculer.','Comparer la puissance calculée à une limite fournie.'],
'Si l’axe est en mA, sa valeur numérique n’est pas en A : diviser directement 6 V par 30 donne une erreur d’un facteur 1 000 sur la résistance.',[
E('Les symboles','Dans U = RI, que désignent U et R ?@@Donner leurs unités.', r'Tension et résistance.@@Volt, V ; ohm, $\Omega$.'),
E('Convertir',r'Convertir $2{,}2\unite{k\Omega}$ en $\Omega$.@@Convertir 15 mA en A.',r'$2\,200\unite\Omega$.@@$0{,}015\unite A$.',calculs=[('2.2*1000',2200),('15/1000',.015)]),
E('Trouver U',r'Calculer U pour $R=100\unite\Omega$ et $I=0{,}020\unite A$.@@Donner la relation utilisée.',r'$2{,}0\unite V$.@@$U=RI$.',calculs=[('100*.02',2)]),
E('Trouver I',r'Calculer I sous 6 V pour $R=300\unite\Omega$.@@Exprimer en mA.',r'$I=0{,}020\unite A$.@@$20\unite{mA}$.',calculs=[('6/300',.02)]),
E('Trouver R',r'Un dipôle ohmique reçoit 3 V sous 10 mA. Calculer R.@@Peut-on trouver R par U/I à l’origine où U = I = 0 ?',r'$R=3/0{,}010=300\unite\Omega$.@@Non : le quotient $0/0$ n’est pas défini.',calculs=[('3/.01',300)]),
E('Une puissance',r'Une lampe en continu reçoit 12 V sous 0,50 A. Calculer P.@@Quelle énergie reçoit-elle chaque seconde ?',r'$6\unite W$.@@$6\unite J$ par seconde à puissance constante.',calculs=[('12*.5',6)]),
E('Retrouver l’intensité',r'Un appareil continu de 24 W fonctionne sous 12 V. Trouver I.@@Un second appareil de 12 W sous 12 V demande quelle intensité ?',r'$I=P/U=2\unite A$.@@$1\unite A$.',calculs=[('24/12',2),('12/12',1)]),
E('Une caractéristique',r'On relève (I en A ; U en V) : (0,01 ; 1), (0,02 ; 2), (0,03 ; 3). Trouver R.@@Quel contrôle graphique effectuer ?',r'$U/I=100\unite\Omega$ pour chaque point.@@Vérifier l’alignement sur une droite proche de l’origine, avec dispersion compatible avec les mesures.',calculs=[('1/.01',100)]),
E('Une limite dépassée',r'Une résistance de $100\unite\Omega$ sous 10 V est limitée à 0,25 W. Calculer I puis P.@@Le choix respecte-t-il la limite ?',r'$I=0{,}10\unite A$ ; $P=1{,}0\unite W$.@@Non, la puissance calculée est quatre fois la limite ; ne pas réaliser ce montage.',calculs=[('10/100',.1),('10*.1',1)]),
E('À tension constante','R double sous la même tension. Que devient I ?@@Que devient P = UI ?', 'I est divisée par deux.@@P est également divisée par deux dans ce modèle.'),
E('À résistance constante','U double et R reste constante. Comment évolue I ?@@Comment évolue P ?', 'I double.@@P est multipliée par quatre, car U et I doublent.'),
E('Une lampe réelle','Une lampe donne U/I = 20 Ω puis 35 Ω à deux fonctionnements. Est-elle ohmique à R constante sur cet intervalle ?@@Quelle cause physique peut contribuer à cette variation ?', 'Non : les quotients diffèrent au-delà des éventuelles erreurs à examiner.@@L’échauffement du filament peut modifier sa résistance.'),
E('Un graphique trompeur','Un graphe porte U horizontalement et I verticalement. Sa pente vaut-elle R ?@@Comment retrouver R sur un point hors origine ?',r'Non ; la pente I/U vaut $1/R$ pour le modèle ohmique.@@Calculer $U/I$ avec I en A.'),
E('Deux branches',r'Deux résistances de 100 Ω et 200 Ω sont en dérivation sous 6 V. Trouver leurs courants.@@Calculer la puissance totale reçue.',r'$I_1=0{,}060\unite A$ et $I_2=0{,}030\unite A$.@@$P=6(0{,}060+0{,}030)=0{,}54\unite W$.',calculs=[('6/100',.06),('6/200',.03),('6*(.06+.03)',.54)]),
E('Choisir un dipôle',r'Un conducteur doit être parcouru par 20 mA sous 5 V. Trouver R et P.@@Une limite de 0,125 W convient-elle dans le modèle ? Discuter la marge.',r'$R=250\unite\Omega$ ; $P=0{,}10\unite W$.@@Oui, le calcul est inférieur à la limite ; la marge reste faible et les tolérances réelles doivent être vérifiées par le responsable du montage.',calculs=[('5/.02',250),('5*.02',.1)])],
E('Une résistance pour le laboratoire',r'On dispose de résistances de 100 Ω ou 220 Ω, chacune limitée à 0,25 W. La tension continue maximale est 6 V. Calculer I et P pour chaque choix.@@Quel choix respecte la limite donnée ?@@Décrire les mesures qui permettraient de contrôler le fonctionnement sans confondre les deux appareils.',r'100 Ω : 60 mA et 0,36 W. 220 Ω : environ 27,3 mA et 0,164 W.@@220 Ω respecte la limite ; 100 Ω la dépasse.@@A en série, V aux bornes de la résistance, calibres et bornes vérifiés ; couper avant modification et rester dans les limites du matériel.',calculs=[('6*(6/100)',.36),('6*(6/220)',.16363636363636364)])),
]
